// Error Trigger payload has execution metadata + error, not node data. Still redact:
// error messages from HTTP nodes can echo request bodies (phone numbers, names).
const e = $json.execution || {};
const msg = String(e.error?.message || 'unknown').slice(0, 500)
  .replace(/\+?\d[\d\s().-]{7,}\d/g, '[phone]')
  .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[email]');
const status = Number(e.error?.httpCode || e.error?.context?.httpCode || 0);
const retryable = status === 0 || status === 429 || status >= 500;
return [{ json: {
  workflow: $json.workflow?.name || 'unknown',
  node: e.lastNodeExecuted || null,
  error: msg,
  retryable,
  payload: { executionId: e.id || null, url: e.url || null, mode: e.mode || null },
}}];
